// NEURO kit common helpers.
// Soft membrane rim for a disc of signed distance d (negative inside), width w.
float membrane(float d, float w) { return exp(-d * d / (w * w)); }
// Tapered segment glow: returns (core, halo).
vec2 fiber(float d, float w) { return vec2(1.0 - smoothstep(w * 0.5, w * 0.5 + aa(), d), glow2(d, w * 1.5)); }

files.styles/action-potential.glsl:
// Action Potential — myelinated axons; the spike leaps node to node (saltatory conduction) as ions flood each node of Ranvier.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0); float cover = 0.0; float px = aa();
  float n = float(p_axons);
  for (int i = 0; i < 8; i++) {
    if (i >= p_axons) break;
    float fi = float(i); vec2 hi = h22(vec2(fi, 1.3));
    float y0 = n > 1.0 ? mix(-A.y * 0.78, A.y * 0.78, (fi + 0.5) / n) : 0.0;
    float depth = n > 1.0 ? hi.y : 0.0;
    float blur = 1.0 + depth * 5.0 * p_depth;
    float k = 2.0 + 3.0 * hi.x, ph = TAU * hi.y;
    float wav = p_wave * 0.06;
    float fy = y0 + wav * sin(uv.x * k + ph) + wav * 0.5 * ln2(vec2(uv.x * 1.5, fi * 3.0), 1.0, 0.25);
    float slope = wav * k * cos(uv.x * k + ph);
    float d = abs(uv.y - fy) / sqrt(1.0 + slope * slope);
    float sp = p_spacing * 0.2;
    float xs = uv.x + A.x + hi.x * sp;
    float cell = floor(xs / sp), fx = fract(xs / sp);
    float node = abs(fx - 0.5) * sp;
    float gap = 0.01;
    float sheathR = 0.017 * p_sheath * (1.0 - 0.3 * depth);
    float axonR = 0.004;
    float inSheath = smoothstep(gap, gap + 0.012, node);
    float rad = mix(axonR, sheathR, inSheath);
    float edge = px * blur;
    float body = 1.0 - smoothstep(rad - edge, rad + edge, d);
    float nz = sqrt(sat(1.0 - (d / max(rad, 1e-4)) * (d / max(rad, 1e-4))));
    float nodes = ceil(2.0 * A.x / sp) + 2.0;
    float s = fract(float(p_rate) * u_p + hi.x) * nodes;
    float sn = floor(s) + pow(fract(s), 1.0 + 7.0 * p_saltation);
    float act = exp(-pow((cell - sn) * 1.4, 2.0));
    float trail = exp(-max(sn - cell, 0.0) * 1.0) * step(cell, sn + 0.5) * 0.3;
    float lam = 0.5 + 0.5 * sin(nz * 22.0 + fx * 3.0 + fi);
    vec3 sheathCol = u_ink * (0.12 + 0.42 * nz + 0.12 * lam * p_detail) * inSheath;
    vec3 coreCol = mix(u_a0 * 0.4, u_a1 * 1.6, act + trail) * (1.0 - inSheath);
    float fade = 1.0 - depth * 0.6 * p_depth;
    col += (sheathCol + coreCol) * body * fade;
    float rn = length(vec2(node, d)); float ng = gauss1(rn, 0.01 * sqrt(blur)) + 0.2 * glow2(rn, 0.01);
    col += u_a1 * (act + trail) * ng * 2.2 * p_glow * fade;
    col += u_a0 * act * gauss1(rn, 0.035) * 0.2 * p_glow;
    cover = max(cover, body * fade);
    if (p_ions > 0.0 && act > 0.05) {
      for (int j = 0; j < 12; j++) {
        vec2 hj = h22(vec2(fi * 13.0 + float(j), cell));
        if (hj.x > p_ions) continue;
        float life = fract(hj.y * 3.1 + s * 1.7);
        float dir = fract(hj.x * 7.0) < 0.5 ? -1.0 : 1.0;
        vec2 c0 = vec2((cell + 0.5) * sp - A.x - hi.x * sp, fy);
        vec2 pp = c0 + vec2((hj.y - 0.5) * 0.035, dir * (0.06 - 0.055 * life));
        float dd = length(uv - pp) - 0.0022;
        col += mix(u_a2, u_ink, step(0.5, hj.y)) * (1.0 - smoothstep(0.0, px, dd)) * act * sin(PI * life) * 1.6;
      }
    }
  }
  if (p_trace) {
    float yb = -A.y + 0.1;
    float x = (uv.x + A.x) / (2.0 * A.x);
    float ph2 = fract(x - u_p * float(p_rate));
    float v = exp(-pow((ph2 - 0.1) * 30.0, 2.0)) - 0.25 * exp(-pow((ph2 - 0.16) * 14.0, 2.0));
    float yy = yb + v * 0.07;
    float dt = abs(uv.y - yy);
    col += u_a1 * line(dt, 0.0028) + u_a1 * glow2(dt, 0.006) * 0.15;
    col += u_ink * 0.1 * line(abs(uv.y - yb), 0.001);
  }
  col = aces(col * 1.2);
  return vec4(col, max(cover * 0.95, max(col.r, max(col.g, col.b))));
}

files.styles/calcium-wave.glsl:
// Calcium Wave — two-photon view of a neural field: GCaMP cells flash and spreading waves ripple through the network.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float sc = 7.0 * p_density;
  vec2 p = uv * sc;
  vec2 n = floor(p);
  vec3 col = vec3(0.0);
  // neuropil haze
  float haze = lfbm(uv * 6.0, 4, 1.0, 0.25) * 0.5 + 0.5;
  // waves: expanding rings from origins
  float waveField = 0.0;
  for (int w = 0; w < 4; w++) {
    if (w >= p_waves) break;
    vec2 h = h22(vec2(float(w), 77.0));
    vec2 o = (h - 0.5) * A * 1.6;
    float ph = fract(u_p * float(p_waveSpeed) + h.x);
    float r = ph * 1.4;
    float d = length(uv - o) - r;
    waveField += exp(-d * d * 180.0) * (1.0 - ph) + exp(-max(-d, 0.0) * 6.0) * step(d, 0.0) * (1.0 - ph) * 0.35;
  }
  col += u_a0 * haze * p_haze * (0.05 + 0.25 * waveField);
  float cover = 0.0;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 c = n + vec2(float(i), float(j));
    vec3 h = h33(vec3(c, 3.0));
    if (h.z > 0.8) continue;
    vec2 site = c + 0.2 + 0.6 * h.xy;
    vec2 d = p - site;
    float depth = h.z;
    float r = 0.16 * p_soma * (0.7 + 0.6 * h.x);
    float ds = length(d) - r;
    float blur = 0.02 + depth * 0.25 * p_focus;
    float soma = 1.0 - smoothstep(-blur, blur, ds);
    // dendrite stubs
    float den = 0.0;
    for (int k = 0; k < 3; k++) {
      float a = TAU * h11(h.x * 10.0 + float(k)) ;
      vec2 e = vec2(cos(a), sin(a)) * (0.35 + 0.3 * h.y) * p_dendrites;
      den = max(den, 1.0 - smoothstep(0.015, 0.04 + blur, sdSeg(d, vec2(0.0), e)));
    }
    // activity: spontaneous events (slot-based, limited) + the wave arriving at this cell
    float slot = tslot(12.0 * p_rate + 1.0);
    float ev = step(1.0 - 0.18 * p_rate, h11(slot * 7.13 + h.x * 91.0));
    float ft = tfrac(12.0 * p_rate + 1.0);
    float spont = ev * smoothstep(0.0, 0.12, ft) * exp(-ft * 4.0 / p_decay);
    vec2 wc = site / sc;
    float wv = 0.0;
    for (int w = 0; w < 4; w++) {
      if (w >= p_waves) break;
      vec2 hw = h22(vec2(float(w), 77.0));
      vec2 o = (hw - 0.5) * A * 1.6;
      float ph = fract(u_p * float(p_waveSpeed) + hw.x);
      float dd = length(wc - o) - ph * 1.4;
      wv += exp(-max(-dd, 0.0) * 8.0 / p_decay) * step(dd, 0.0) * (1.0 - ph);
    }
    float act = sat(spont + wv) * p_brightness;
    float base = 0.18 + 0.12 * h.y;
    float fade = 1.0 - depth * 0.6 * p_focus;
    vec3 c3 = mix(u_a0 * base, mix(u_a0, u_ink, 0.55) * 1.6, act);
    col += c3 * (soma + den * 0.45) * fade + u_a0 * act * glow2(max(ds, 0.0), 0.25) * 0.25 * fade;
    // nucleus shadow (GCaMP is cytosolic)
    col *= 1.0 - 0.55 * (1.0 - smoothstep(-0.02, 0.03, length(d) - r * 0.45)) * soma;
    cover = max(cover, soma * fade);
  }
  if (p_scan) col *= 0.9 + 0.1 * sin(fc.y * 1.7);
  col = aces(col * 1.2);
  return vec4(col, max(cover, max(col.r, max(col.g, col.b))));
}

files.styles/chromatin.glsl:
// Chromatin — the double helix turns, unzips at a replication fork and zips back; nucleosome beads drift behind.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec2 q = rot(p_tilt * 0.6) * uv / p_scale;
  vec3 col = vec3(0.0); float cover = 0.0; float px = aa() / p_scale;
  // background nucleosomes: soft beads with wrapped DNA
  for (int i = 0; i < 10; i++) {
    if (float(i) >= p_beads * 10.0) break;
    vec3 h = h33(vec3(float(i), 4.0, 8.0));
    vec2 c = (h.xy - 0.5) * A * 2.2 / p_scale + 0.04 * lc(1.0, h.z);
    float r = 0.05 + 0.03 * h.z;
    float d = length(q - c) - r;
    float blur = 0.02 + 0.03 * p_fog;
    float bead = 1.0 - smoothstep(-blur, blur, d);
    float wrap = line(abs(fract((dot(q - c, vec2(0.8, 0.6)) / r) * 1.7 + u_p * 0.0) - 0.5) * r, 0.01) * bead;
    col += (u_a2 * 0.18 * bead + u_a2 * 0.12 * wrap) * (1.0 - 0.6 * p_fog);
  }
  float R = 0.07;
  float turns = 10.0 * p_turns;
  float th0 = TAU * float(p_twist) * u_p;
  // fork position sweeps along the helix and back
  float fork = mix(-A.x / p_scale - 0.2, A.x / p_scale * 0.6, p_unzip * (0.5 - 0.5 * cos(TAU * u_p)));
  float x = q.x;
  float th = x * turns + th0;
  float open = max(fork - x, 0.0);
  float sep = open * 0.55;
  float yA = R * sin(th) + sep, zA = cos(th);
  float yB = R * sin(th + PI * 0.75) - sep, zB = cos(th + PI * 0.75);
  float bw = 0.009 * p_width;
  // base pairs (rungs) on a fixed lattice along x
  float bp = 0.028 / p_basePairs;
  float xi = floor(x / bp + 0.5);
  float xr = xi * bp;
  float thr = xr * turns + th0;
  float oR = max(fork - xr, 0.0);
  float ya = R * sin(thr) + oR * 0.55, yb = R * sin(thr + PI * 0.75) - oR * 0.55;
  float zr = (cos(thr) + cos(thr + PI * 0.75)) * 0.5;
  float dx = abs(x - xr);
  float ymin = min(ya, yb), ymax = max(ya, yb);
  float inRung = step(ymin, q.y) * step(q.y, ymax);
  float zipped = 1.0 - smoothstep(0.0, 0.03, oR);
  float stubLen = mix(ymax - ymin, 0.03, 1.0 - zipped);
  float fromA = abs(q.y - ya), fromB = abs(q.y - yb);
  float rungMask = zipped > 0.5 ? inRung : max(step(fromA, stubLen) * step(0.0, (q.y - ya) * sign(yb - ya)), step(fromB, stubLen) * step(0.0, (q.y - yb) * sign(ya - yb)));
  float rung = (1.0 - smoothstep(0.0025, 0.0025 + px, dx)) * rungMask;
  float base = floor(h11(xi + 13.0) * 4.0);
  float half_ = step(abs(q.y - ya), abs(q.y - yb));
  vec3 bcol = p_rungMode == RUNG_MODE_BASES ? accent(base + half_ * 2.0) : mix(u_a0, u_a1, half_);
  if (base > 2.5) bcol = mix(bcol, u_ink, 0.5);
  float depthR = 0.45 + 0.55 * sat(zr * 0.5 + 0.5);
  // strands: draw back strand first, then front
  float dA = abs(q.y - yA), dB = abs(q.y - yB);
  float sA = 1.0 - smoothstep(bw - px, bw + px, dA);
  float sB = 1.0 - smoothstep(bw - px, bw + px, dB);
  vec3 cA = u_ink * (0.35 + 0.65 * sat(zA * 0.5 + 0.5)) + u_a0 * glow2(dA, bw * 2.0) * 0.25 * p_glow;
  vec3 cB = u_ink * (0.35 + 0.65 * sat(zB * 0.5 + 0.5)) + u_a1 * glow2(dB, bw * 2.0) * 0.25 * p_glow;
  vec4 layerR = vec4(bcol * depthR, 1.0) * rung;
  vec4 layerA = vec4(cA, 1.0) * sA, layerB = vec4(cB, 1.0) * sB;
  vec4 back = zA < zB ? layerA : layerB, front = zA < zB ? layerB : layerA;
  vec4 acc = vec4(col, 0.0);
  acc = over(layerR, acc);
  acc = over(zA < 0.0 && zB < 0.0 ? back : back, acc);
  acc = over(front, acc);
  // polymerase glow at the fork
  float df = length(vec2(q.x - fork, q.y));
  acc.rgb += u_a2 * glow2(df, 0.03) * 0.6 * p_glow * p_unzip;
  vec3 outc = aces(acc.rgb * 1.1);
  return vec4(outc, max(acc.a, max(max(outc.r, outc.g), outc.b)));
}

files.styles/confocal.glsl:
// Confocal — a z-stack sweeps through cultured neurons: three fluorescence channels drift in and out of focus.
vec3 CF_channels(vec2 p, float zf) {
  // green: neurites and somata (ridged 3D noise sliced at the focal plane)
  float r1 = 1.0 - abs(snoise(vec3(p * 3.0 * p_neurites, zf * 1.2) + vec3(M_seedOff(), 0.0)));
  float r2 = 1.0 - abs(snoise(vec3(p * 6.5 * p_neurites, zf * 2.0 + 3.0) + vec3(M_seedOff(), 0.0)));
  float neur = pow(r1, 18.0) + 0.5 * pow(r2, 22.0);
  float somaF = 0.0, nucF = 0.0, punc = 0.0;
  vec2 g = p * 2.2 * p_density;
  vec2 n = floor(g);
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 c = n + vec2(float(i), float(j)); vec3 h = h33(vec3(c, 1.0));
    vec2 s = c + 0.2 + 0.6 * h.xy;
    float zc = (h.z - 0.5) * 2.0;
    float foc = exp(-pow((zf - zc) * 1.6, 2.0));
    float d = length((g - s) * vec2(1.0, 1.2));
    somaF += exp(-d * d * 40.0) * foc * 1.4;
    nucF += exp(-pow(d * 9.0, 4.0)) * foc;
  }
  vec2 pg = p * 26.0 * p_puncta;
  vec2 pn = floor(pg);
  vec3 hp = h33(vec3(pn, 7.0));
  if (hp.z < 0.35) {
    float zc = (hp.x - 0.5) * 2.0;
    float d = length(pg - pn - 0.5 - (hp.xy - 0.5) * 0.6);
    punc = exp(-d * d * 16.0) * exp(-pow((zf - zc) * 2.5, 2.0)) * (0.5 + neur * 2.0);
  }
  return vec3(neur * 0.9 + somaF, punc * 1.8, nucF * 0.9);
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float zf = p_sweep * 1.3 * sin(TAU * u_p * float(p_sweepSpeed));
  vec2 p = uv;
  bool quad = p_view == VIEW_QUAD;
  int panel = 3;
  if (quad) {
    vec2 s = step(vec2(0.0), uv);
    panel = int(s.x + 2.0 * (1.0 - s.y));
    p = (uv - (s - 0.5) * A) * 2.0;
  }
  vec3 ch = CF_channels(p, zf) * p_gain;
  // detector noise (static pattern + slow shot noise, flash-safe)
  float nz = (h21(floor(fc * 0.5) + tslot(24.0)) - 0.5) * 0.12 * p_noise;
  ch = max(ch + nz, 0.0);
  // with every channel switched off the detector would show nothing: fall back to the merged view
  bool none = !p_green && !p_magenta && !p_blue;
  vec3 m = vec3(p_green || none ? ch.x : 0.0, p_magenta || none ? ch.y : 0.0, p_blue || none ? ch.z : 0.0);
  if (quad && panel < 3) m = panel == 0 ? vec3(m.x, 0.0, 0.0) : panel == 1 ? vec3(0.0, m.y, 0.0) : vec3(0.0, 0.0, m.z);
  vec3 col = u_a0 * m.x + u_a1 * m.y + u_a2 * m.z;
  if (quad) { vec2 gl = abs(uv); col += u_ink * 0.3 * (line(gl.x, 0.002) + line(gl.y, 0.002)); }
  // scale bar
  vec2 sb = uv - vec2(A.x - 0.16, -A.y + 0.05);
  col += u_ink * 0.8 * (1.0 - smoothstep(0.0, aa(), sdBox(sb, vec2(0.08, 0.004))));
  col = aces(col * 1.2);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/connectome.glsl:
// Connectome — tractography bundles arc through a rotating brain volume; signal pulses stream along every fibre.
vec4 motif(vec2 uv, vec2 fc) {
  vec3 col = vec3(0.0); float cover = 0.0;
  float rotA = TAU * u_p * float(p_spin) * step(0.5, p_turn) + p_turn * 0.9 * lsin(1.0, 0.0);
  float cy = cos(rotA);
  for (int b = 0; b < 8; b++) {
    if (b >= p_bundles) break;
    float fb = float(b); vec3 h = h33(vec3(fb, 2.0, 5.0));
    // each bundle: family of elliptical arcs (level sets of a scaled radius), centre + tilt
    vec2 c = (h.xy - 0.5) * vec2(0.5, 0.25);
    float tilt = (h.z - 0.5) * 2.2;
    float zc = (h.x - 0.5) * 0.6; // depth of bundle
    vec2 cc = vec2(c.x * cy + zc * sin(rotA), c.y);
    vec2 q = rot(tilt) * (uv - cc);
    float sx = (0.25 + 0.3 * h.y) * mix(1.0, abs(cy) * 0.8 + 0.2, p_turn * 0.8);
    float sy = 0.18 + 0.2 * h.z;
    q += p_warp * 0.05 * vec2(ln2(q * 3.0 + fb, 1.0, 0.3), ln2(q * 3.0 - fb, 1.0, 0.3));
    vec2 e = q / vec2(sx, sy);
    float r = length(e);
    float th = atan(e.y, e.x);
    // arc spans an angular window (a "C" shape)
    float span = mix(0.35, 0.95, p_spread) * PI;
    float thc = th - (h.x - 0.5) * PI;
    thc = mod(thc + PI, TAU) - PI;
    float win = smoothstep(span, span * 0.8, abs(thc));
    float band = smoothstep(0.55, 0.62, r) * (1.0 - smoothstep(1.0, 1.08, r));
    float N = 14.0 * p_density;
    float lr = r * N + 0.3 * sin(th * 3.0 + fb);
    float fid = floor(lr);
    float fl = abs(fract(lr) - 0.5);
    float wpx = aa() * N / max(sx, sy);
    float fibre = 1.0 - smoothstep(0.08 * p_width, 0.08 * p_width + wpx * 1.5, fl);
    float halo = gauss1(fl, 0.25);
    float hf = h11(fid + fb * 50.0);
    // pulses along the fibre (angle coordinate)
    float s = (thc / span) * 0.5 + 0.5;
    float pl = pulse(s * 1.2, float(p_flow), hf, 0.06 * p_pulse + 0.01);
    // direction colour (DTI style): orientation of the fibre tangent
    vec2 tang = normalize(vec2(-e.y * sx, e.x * sy));
    tang = rot(-tilt) * tang;
    vec3 dirCol = p_dirColour ? normalize(abs(vec3(tang.x, tang.y, 0.55 * abs(h.z - 0.5) + 0.2))) : vec3(1.0);
    vec3 base = p_dirColour ? (u_a0 * dirCol.x + u_a1 * dirCol.y + u_a2 * dirCol.z) : mix(u_a0, u_a2, hf);
    float depthF = 1.0 - p_fog * sat(0.5 + (zc * cos(rotA) - c.x * sin(rotA)) * 1.2);
    float m = band * win * depthF;
    col += base * (fibre * (0.35 + 0.65 * hf) + halo * 0.05 * p_glow) * m + mix(base, u_ink, 0.6) * pl * (fibre * 2.2 + halo * 0.35 * p_glow) * m;
    cover = max(cover, fibre * m * 0.8);
  }
  col = aces(col);
  return vec4(col, max(cover, max(col.r, max(col.g, col.b))));
}

files.styles/cortical-fold.glsl:
// Cortical Fold — gyri and sulci wrap a turning hemisphere while waves of activity sweep the surface.
// Gyri as a labyrinth: band-limited random plane waves (same wavelength), thresholded near zero.
float foldH(vec3 P) {
  P += p_warp * 0.12 * vec3(ln3(P * 2.0, float(p_flow), 0.2), ln3(P * 2.0 + 5.0, float(p_flow), 0.2), 0.0);
  float k = 52.0 * p_folds, f = 0.0;
  for (int i = 0; i < 14; i++) {
    vec3 h = h33(vec3(float(i), 2.0, 9.0));
    float z = h.x * 2.0 - 1.0, a = h.y * TAU; vec3 d = vec3(sqrt(1.0 - z * z) * vec2(cos(a), sin(a)), z);
    f += cos(k * dot(P, d) + h.z * TAU + TAU * u_p * float(p_flow) * (h.z < 0.5 ? 1.0 : -1.0));
  }
  f /= sqrt(14.0);
  return smoothstep(-0.55, 0.55, f);
}
vec4 motif(vec2 uv, vec2 fc) {
  float R = 0.42;
  vec2 q = uv;
  float r2 = dot(q, q) / (R * R);
  float globe = p_globe;
  float inside = 1.0 - smoothstep(1.0 - aa() * 3.0 / R, 1.0, r2) ;
  float z = sqrt(max(0.0, 1.0 - r2));
  // sphere mapping (blend with flat plane)
  float spin = TAU * u_p * float(p_spin);
  vec3 n0 = vec3(q / R, z);
  n0.xz = rot(spin) * n0.xz;
  vec3 P = mix(vec3(uv * 2.2, 0.0), n0, globe);
  vec2 tuv = P.xy * 4.0;
  float e = 0.0025;
  float h = foldH(P), hx = foldH(P + vec3(e, 0.0, 0.0)), hy = foldH(P + vec3(0.0, e, 0.0));
  vec3 bump = normalize(vec3(-(hx - h) / e * 0.02, -(hy - h) / e * 0.02, 1.0 / (p_depth + 0.05)));
  vec3 N = normalize(mix(vec3(0.0, 0.0, 1.0), vec3(q / R, z), globe * inside));
  // perturb the base normal by the bump
  vec3 T = normalize(cross(vec3(0.0, 1.0, 0.0), N) + 1e-4), B = cross(N, T);
  vec3 Np = normalize(T * bump.x + B * bump.y + N * bump.z);
  vec3 L = normalize(vec3(cos(p_light * TAU), sin(p_light * TAU), 0.9));
  float dif = sat(dot(Np, L));
  float spec = pow(sat(dot(reflect(-L, Np), vec3(0.0, 0.0, 1.0))), 24.0) * p_specular;
  float ao = mix(0.35, 1.0, h);
  // activity: travelling bands across the cortex
  float act = 0.0;
  for (int i = 0; i < 3; i++) {
    vec2 hh = h22(vec2(float(i), 11.0));
    vec2 dir = normalize(hh - 0.5);
    float s = dot(tuv, dir) * 0.35 - float(p_waves) * u_p - hh.x;
    act += pow(0.5 + 0.5 * sin(TAU * s), 12.0);
  }
  act *= p_activity * h;
  vec3 tissue = mix(u_a2 * 0.35, mix(u_ink, u_a2, 0.35), h);
  vec3 col = tissue * (0.15 + 0.85 * dif) * ao + u_ink * spec + u_a0 * act * 1.4;
  float rim = pow(1.0 - z, 3.0) * globe;
  col += u_a1 * rim * p_rim * 1.5;
  float a = mix(1.0, inside, globe);
  col = aces(col * 1.1);
  return vec4(col * a, a);
}

files.styles/eeg-cascade.glsl:
// EEG Cascade — multichannel traces scroll over a live spectrogram waterfall; spikes and spindles ripple across channels.
float EEG_sig(float x, float ch) {
  // x in loop units (periodic with period 1); sum of band oscillations with integer cycles per loop
  float s = 0.0;
  float d = float(p_speed);
  s += 0.9 * sin(TAU * (x * 3.0 + h11(ch)));                         // delta
  s += 0.6 * sin(TAU * (x * 9.0 + h11(ch + 1.0))) * (0.5 + 0.5 * sin(TAU * (x * 2.0 + ch * 0.1)));  // theta
  s += p_alpha * 1.3 * sin(TAU * (x * 24.0 + h11(ch + 2.0))) * pow(0.5 + 0.5 * sin(TAU * (x + ch * 0.07)), 2.0); // alpha spindles
  s += 0.35 * sin(TAU * (x * 61.0 + h11(ch + 3.0)));                  // beta
  s += p_noise * 0.6 * snoise(vec4(cos(TAU * x) * 9.0, sin(TAU * x) * 9.0, ch * 3.1, 0.0)); // broadband noise
  // spikes: sharp transients at hashed loop positions, propagating across channels
  for (int k = 0; k < 6; k++) {
    if (float(k) >= p_spikes * 6.0) break;
    float at = h11(float(k) + 40.0) + ch * 0.004 * (h11(float(k) + 41.0) - 0.5);
    float dx = fract(x - at + 0.5) - 0.5;
    s += 3.0 * exp(-dx * dx * 60000.0) - 1.2 * exp(-pow(dx - 0.004, 2.0) * 9000.0);
  }
  return s * 0.25;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float x01 = (uv.x + A.x) / (2.0 * A.x);
  float x = x01 * 0.5 + u_p * float(p_speed) ;
  vec3 col = vec3(0.0); float cover = 0.0;
  // spectrogram waterfall: frequency up, time across, periodic in x
  float fy = (uv.y + A.y) / (2.0 * A.y);
  float band = 0.0;
  band += exp(-pow((fy - 0.08) * 14.0, 2.0)) * (0.7 + 0.3 * sin(TAU * (x * 2.0)));
  band += p_alpha * exp(-pow((fy - 0.3) * 18.0, 2.0)) * pow(0.5 + 0.5 * sin(TAU * x), 2.0) * 1.3;
  band += 0.5 * exp(-pow((fy - 0.55) * 8.0, 2.0)) * (0.5 + 0.5 * snoise(vec4(cos(TAU * x) * 3.0, sin(TAU * x) * 3.0, fy * 6.0, 1.0)));
  band += 0.25 * (0.5 + 0.5 * snoise(vec4(cos(TAU * x) * 12.0, sin(TAU * x) * 12.0, fy * 30.0, 2.0)));
  band = pow(sat(band * p_contrast * 0.8), 1.4);
  col += ramp(0.1 + band * 0.9) * p_spectro;
  // grid
  if (p_grid) {
    float gx = abs(fract(x01 * 16.0) - 0.5) * 2.0 * A.x / 16.0, gy = abs(fract(fy * 10.0) - 0.5) * 2.0 * A.y / 10.0;
    col += u_ink * 0.06 * (line(gx, 0.001) + line(gy, 0.001));
  }
  // traces
  int C = p_channels;
  float lane = 2.0 * A.y * 0.9 / float(C);
  float y0 = A.y * 0.9;
  float ci = floor((y0 - uv.y) / lane);
  for (int k = -1; k <= 1; k++) {
    float ch = ci + float(k);
    if (ch < 0.0 || ch >= float(C)) continue;
    float yc = y0 - (ch + 0.5) * lane;
    float amp = lane * 0.9 * p_amplitude;
    float v = EEG_sig(x, ch) * amp;
    float dx = 1.0 / (u_res.x) * 0.5;
    float v2 = EEG_sig(x + dx, ch) * amp;
    float slope = (v2 - v) / (dx * 2.0 * A.x / 0.5);
    float d = abs(uv.y - (yc + v)) / sqrt(1.0 + slope * slope);
    vec3 tc = mix(u_a0, u_a1, h11(ch + 9.0) * 0.6);
    col += tc * line(d, 0.0022 * p_lineWidth) * 1.4 + tc * glow2(d, 0.004 * p_lineWidth) * 0.12 * p_glow;
    cover = max(cover, line(d, 0.0022 * p_lineWidth));
    col += u_ink * 0.05 * line(abs(uv.y - yc), 0.0008);
  }
  // playhead
  float ph = abs(x01 - 0.82) * 2.0 * A.x;
  col += u_a2 * line(ph, 0.002) * 0.8;
  col = aces(col * 1.1);
  return vec4(col, max(cover, max(max(col.r, col.g), col.b)));
}

files.styles/epithelium.glsl:
// Epithelium — living tissue: domed cells jostle and breathe, nuclei drift, a calcium wave rolls through.
vec4 motif(vec2 uv, vec2 fc) {
  float sc = 9.0 / p_cellSize;
  vec2 p = uv * sc;
  p += p_texture * 0.25 * vec2(ln2(uv * 3.0, 1.0, 0.3), ln2(uv * 3.0 + 4.0, 1.0, 0.3));
  vec2 n = floor(p), f = fract(p);
  float d1 = 9.0, d2 = 9.0; vec2 site = vec2(0.0); float id = 0.0; vec2 cellN = vec2(0.0);
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 g = vec2(float(i), float(j)); vec2 h = h22(n + g);
    vec2 o = 0.5 + p_jitter * (h - 0.5) + 0.12 * p_motion * lc(float(p_speed), h.x);
    vec2 r = g + o - f;
    // breathing: each cell's weight oscillates (power-diagram style)
    float wgt = 0.08 * p_breathe * lsin(float(p_speed), h.y);
    float d = length(r) - wgt;
    if (d < d1) { d2 = d1; d1 = d; site = r; id = h.x; cellN = n + g; } else if (d < d2) d2 = d;
  }
  float edge = d2 - d1;
  float mw = 0.06 * p_membrane;
  float memb = 1.0 - smoothstep(mw, mw + 0.05, edge);
  float dome = sat(edge * 2.2);
  // nucleus: ellipse near the site, slowly rotating
  vec2 nq = rot(TAU * (id + 0.15 * lsin(1.0, id))) * site;
  float nuc = length(nq / vec2(1.0, 0.7)) - 0.22 * p_nucleus;
  float nucIn = 1.0 - smoothstep(-0.02, 0.02, nuc);
  // calcium wave: rolls across the tissue by cell centroid, k times per loop
  vec2 cw = (cellN + 0.5) / sc;
  float wave = pulse(dot(cw, normalize(vec2(1.0, 0.35))) * 0.6 + 0.5, float(p_waveSpeed), 0.0, 0.08 * p_waveWidth + 0.02);
  float lit = wave * (0.6 + 0.4 * id);
  vec3 col; float a;
  if (p_stain == STAIN_HE) {
    // H&E histology: pink cytoplasm, purple nuclei, pale membranes
    vec3 cyto = mix(u_a2, u_ink, 0.1) * (0.7 + 0.3 * dome);
    col = mix(cyto, u_a1 * 0.9, nucIn) * (0.85 + 0.15 * ln2(p * 3.0, 1.0, 0.2));
    col = mix(col, u_a0, memb * 0.6);
    col = mix(col, u_a0 * 1.3, lit * 0.35);
    a = 1.0;
  } else if (p_stain == STAIN_PHASE) {
    float g = 0.35 + 0.35 * dome - 0.3 * memb + 0.5 * gauss1(edge - mw - 0.04, 0.03) - 0.25 * nucIn;
    col = u_ink * g + u_a0 * lit * 0.3;
    a = 1.0;
  } else {
    // fluorescence: membrane marker, nuclear stain, calcium indicator
    col = u_a0 * memb * 1.2 + u_a0 * 0.08 * dome + u_a2 * nucIn * (0.6 + 0.4 * ln2(nq * 8.0, 1.0, 0.2)) + u_a1 * lit * dome * 1.3;
    col += u_a1 * lit * memb * 0.6;
    col = aces(col);
    a = max(max(col.r, col.g), col.b);
  }
  return vec4(col * (p_stain == STAIN_FLUOR ? 1.0 : 1.0), a);
}

files.styles/grid-cells.glsl:
// Grid Cells — an explorer roams its arena; entorhinal grid cells fire on a hexagonal lattice and spikes pile up where fields are crossed.
float GC_field(vec2 x, float sc, float ori) {
  float k = TAU / (sc * 0.866);
  float s = 0.0;
  for (int i = 0; i < 3; i++) { float a = ori + float(i) * PI / 3.0; s += cos(k * dot(x, vec2(cos(a), sin(a)))); }
  return sat((s + 1.5) / 4.5);
}
float GC_rate(vec2 x) {
  float r = 0.0;
  for (int m = 0; m < 3; m++) {
    if (m >= p_modules) break;
    float sc = p_scale * 0.18 * pow(1.42, float(m));
    float ori = p_orientation * PI / 3.0 + float(m) * 0.17 + 0.05 * p_drift * lsin(1.0, float(m) * 0.3);
    r = max(r, pow(GC_field(x, sc, ori), 1.0 + 6.0 * p_sharp));
  }
  return r;
}
const vec4 GC_M = vec4(1.0, 2.0, 3.0, 4.0);
const vec4 GC_A = vec4(0.36, 0.18, 0.12, 0.09);
vec2 GC_soft(vec2 p) {
  p *= 0.62;
  float l = length(p); float lim = 0.4;
  return l > lim * 0.8 ? p / l * (lim * 0.8 + (lim * 0.2) * tanh((l - lim * 0.8) / (lim * 0.2))) : p;
}
// Path harmonics as rotating phasors (4 harmonics in one vec4): evaluating the path at evenly
// spaced times costs a few multiplies per sample instead of eight trig calls.
void GC_phase(float t, vec4 hx, vec4 hy, out vec4 cx, out vec4 sx, out vec4 cy, out vec4 sy) {
  vec4 ax = TAU * (GC_M * t + hx), ay = TAU * (GC_M * t + hy);
  cx = cos(ax); sx = sin(ax); cy = cos(ay); sy = sin(ay);
}
vec2 GC_at(vec4 cx, vec4 sy) { return GC_soft(vec2(dot(GC_A, cx), dot(GC_A, sy))); }
vec4 motif(vec2 uv, vec2 fc) {
  float R = 0.44;
  float arena = p_arena == ARENA_CIRCLE ? length(uv) - R : sdBox(uv, vec2(R));
  float inside = 1.0 - smoothstep(-aa(), aa(), arena);
  float rate = GC_rate(uv);
  vec3 col = (u_bg * 0.4 + mix(u_a2 * 0.35, u_a0 * 1.3, pow(rate, 1.2)) * pow(rate, 1.3) + u_a0 * 0.35 * pow(rate, 6.0)) * p_heat * inside;
  col += u_ink * 0.5 * line(abs(arena), 0.003);
  float cover = inside * p_heat * 0.9;
  // trail + spikes (samples on a fixed lattice of loop time so they stay put as the trail moves)
  float SPL = 360.0;
  float now = u_p * float(p_speed);
  float i0 = floor(now * SPL);
  float trailN = 40.0 + 200.0 * p_trail;
  vec4 hx, hy;
  for (int m = 0; m < 4; m++) { vec2 h = h22(vec2(float(m + 1), 21.0)); hx[m] = h.x; hy[m] = h.y; }
  vec4 cx, sx, cy, sy;
  GC_phase(now, hx, hy, cx, sx, cy, sy);
  vec2 head = GC_at(cx, sy);
  float dmin = 1e9; float spikes = 0.0;
  vec2 prev = head;
  float stp = max(1.0, floor(trailN / 48.0));
  GC_phase(i0 / SPL, hx, hy, cx, sx, cy, sy);
  vec4 dr = -TAU * GC_M * (stp / SPL); vec4 rc = cos(dr), rs = sin(dr);
  for (int j = 0; j < 48; j++) {
    vec2 pnt = GC_at(cx, sy);
    float age = float(j) / 48.0;
    vec2 pc = clamp(pnt, vec2(-R), vec2(R));
    dmin = min(dmin, sdSeg(uv, prev, pc) + age * 0.004);
    prev = pc;
    vec4 ncx = cx * rc - sx * rs; sx = sx * rc + cx * rs; cx = ncx;
    vec4 ncy = cy * rc - sy * rs; sy = sy * rc + cy * rs; cy = ncy;
  }
  col += u_ink * line(dmin, 0.0025) * 0.55 * inside + u_a2 * glow2(dmin, 0.005) * 0.05;
  // spikes across a long history window
  float sstp = max(1.0, floor(trailN / 20.0));
  GC_phase(i0 / SPL, hx, hy, cx, sx, cy, sy);
  dr = -TAU * GC_M * (sstp / SPL); rc = cos(dr); rs = sin(dr);
  for (int j = 0; j < 90; j++) {
    float idx = i0 - float(j) * sstp;
    vec2 pnt = GC_at(cx, sy);
    vec4 ncx = cx * rc - sx * rs; sx = sx * rc + cx * rs; cx = ncx;
    vec4 ncy = cy * rc - sy * rs; sy = sy * rc + cy * rs; cy = ncy;
    if (length(uv - pnt) > 0.05) continue;
    float r = GC_rate(pnt);
    float im = mod(idx, SPL);
    float hsp = h11(im + 5.0);
    if (hsp > sqrt(r) * p_spikeRate * 0.8) continue;
    vec2 jit = (h22(vec2(im, 3.0)) - 0.5) * 0.012;
    float d = length(uv - pnt - jit);
    float age = float(j) / 90.0;
    spikes += (1.0 - smoothstep(0.005, 0.005 + aa(), d)) * (1.0 - age * 0.6) + glow2(d, 0.008) * 0.3 * (1.0 - age) * p_glow;
  }
  col = mix(col, u_a1 * 1.6, sat(spikes));
  // the animal
  float dh = length(uv - head);
  col += u_ink * (1.0 - smoothstep(0.008, 0.008 + aa(), dh)) + u_a0 * glow2(dh, 0.02) * 0.4 * p_glow;
  cover = max(cover, sat(spikes));
  col = aces(col * 1.1);
  return vec4(col, max(cover, max(max(col.r, col.g), col.b)));
}

files.styles/microtubule-transit.glsl:
// Microtubule Transit — kinesin motors step cargo along a cytoskeletal highway, dynein hauls it back.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0); float cover = 0.0; float px = aa();
  for (int i = 0; i < 20; i++) {
    if (i >= p_filaments) break;
    float fi = float(i); vec3 h = h33(vec3(fi, 9.0, 1.0));
    vec2 c = (h.xy - 0.5) * A * 1.6;
    float ang = (h.z - 0.5) * 2.6 + 0.2 * fi;
    vec2 t = vec2(cos(ang), sin(ang)), nn = vec2(-t.y, t.x);
    vec2 q = uv - c;
    float s = dot(q, t);
    float bend = p_curve * 0.25 * sin(s * 3.0 + fi);
    float dn = dot(q, nn) - bend * 0.1;
    float depth = h.x;
    float blur = 1.0 + depth * 5.0 * p_depth;
    float fade = 1.0 - depth * 0.55 * p_depth;
    float wdt = 0.006 * p_width * (1.0 - 0.4 * depth);
    float d = abs(dn);
    float fil = 1.0 - smoothstep(wdt - px * blur, wdt + px * blur, d);
    // tubulin lattice: 13 protofilaments / 8 nm dimers suggested by a striped texture
    float lat = 0.6 + 0.4 * sin(s * 420.0 * p_lattice + dn * 800.0) * sin(dn / wdt * 3.0 + 0.5);
    col += mix(u_ink * 0.35, u_a0 * 0.8, 0.3 + 0.3 * lat) * fil * fade + u_a0 * glow2(d, wdt * 3.0) * 0.05 * p_glow * fade;
    cover = max(cover, fil * fade);
    // motors with cargo
    for (int j = 0; j < 4; j++) {
      if (j >= p_cargo) break;
      vec2 hj = h22(vec2(fi * 11.0 + float(j), 4.0));
      float dir = p_bidirectional && hj.y < 0.4 ? -1.0 : 1.0;
      float span = 2.4;
      // stepping: a travelling coordinate quantised into discrete steps with an ease in each
      float nsteps = 40.0 * p_stepSize + 8.0;
      float x = fract(u_p * float(p_speed) * (dir > 0.0 ? 1.0 : 1.0) + hj.x) * nsteps;
      float stepx = (floor(x) + smoothstep(0.55, 1.0, fract(x))) / nsteps;
      float along = (stepx - 0.5) * span * dir;
      vec2 base = c + t * along + nn * (p_curve * 0.25 * sin(along * 3.0 + fi) * 0.1);
      float cr = 0.018 * p_cargoSize * (0.7 + 0.6 * hj.y);
      vec2 cp = base + nn * (cr + 0.012);
      float dc = length(uv - cp) - cr;
      float cargo = 1.0 - smoothstep(-px * blur, px * blur, dc);
      vec3 cc = dir > 0.0 ? u_a1 : u_a2;
      col += cc * (cargo * (0.45 + 0.55 * sat(-dc / cr * 2.0)) + glow2(max(dc, 0.0), 0.01) * 0.3 * p_glow) * fade;
      // legs: two heads alternating each step
      float leg = fract(x);
      vec2 foot1 = base + t * (0.006 * (leg < 0.5 ? 1.0 : -1.0) * dir);
      vec2 foot2 = base - t * (0.006 * (leg < 0.5 ? 1.0 : -1.0) * dir);
      vec2 hip = base + nn * 0.012;
      float dl = min(sdSeg(uv, hip, foot1), sdSeg(uv, hip, foot2));
      float legs = 1.0 - smoothstep(0.0015, 0.0015 + px * blur, dl);
      col += mix(cc, u_ink, 0.5) * legs * fade;
      cover = max(cover, max(cargo, legs) * fade);
    }
  }
  col = aces(col * 1.1);
  return vec4(col, max(cover, max(col.r, max(col.g, col.b))));
}

files.styles/mitosis.glsl:
// Mitosis — a cell condenses its chromosomes, aligns them on the spindle, splits in two, and the camera
// follows one daughter until it becomes the parent again: an infinite, seamless division loop.
const float R0 = 0.26;      // parent radius
const float SZ = 1.35;      // generation zoom
const float DD = 0.26;      // daughter offset after division
float st(float a, float b) { return smoothstep(a, b, u_p); }
// Interphase-style cell interior texture in local coords (unit radius), mirrored by m.
float chromatin(vec2 l, float m) { l.x *= m; return lfbm(l * 3.2 * p_detail + 2.0, 4, 1.0, 0.18); }
vec4 motif(vec2 uv, vec2 fc) {
  float camE = st(0.6, 1.0);
  float zoom = pow(SZ, camE);
  vec2 w = uv / zoom + vec2(DD * camE, 0.0);
  float px = aa() / zoom;
  float rD = R0 / SZ;
  // division geometry
  float sep = st(0.4, 0.72);                       // cell body separation
  float d = DD * sep;
  float rc = mix(R0, rD, sep);
  float k = 0.12 * p_cleave * smoothstep(0.36, 0.46, u_p) * (1.0 - smoothstep(0.55, 0.74, u_p)) + 0.001;
  vec2 c1 = vec2(d, 0.0), c2 = vec2(-d, 0.0);
  // local frame of the nearest body centre: parent at p=0 and daughter A at p=1 share textures,
  // daughter B and the cousin share a mirrored frame (keeps the zoom loop seamless)
  float sB = rc / R0;
  bool nearA = w.x >= 0.0;
  vec2 lb = (w - (nearA ? c1 : c2)) / rc; lb.x *= (nearA || sep < 0.001) ? 1.0 : -1.0;
  float body = smin(length(w - c1) - rc, length(w - c2) - rc, k);
  body += 0.004 * sB * ln2(lb * 5.0, 1.0, 0.3) * p_membrane;
  vec2 cc = vec2(-2.0 * DD * SZ, 0.0);
  vec2 lc_ = (w - cc) / R0; lc_.x = -lc_.x;
  float cous = length(w - cc) - R0 + 0.004 * ln2(lc_ * 5.0, 1.0, 0.3) * p_membrane;
  vec3 col = vec3(0.0); float cover = 0.0;
  bool fl = p_stain != STAIN_PHASE;
  vec3 memC = fl ? u_a0 : u_ink * 0.8;
  vec3 dnaC = fl ? u_a2 : u_ink * 0.9;
  vec3 tubC = fl ? u_a1 : u_ink * 0.5;
  for (int i = 0; i < 2; i++) {
    float sc = i == 0 ? sB : 1.0;
    float sd = (i == 0 ? body : cous) / sc;   // distance in parent-equivalent units
    vec2 l = i == 0 ? lb : lc_;
    float pxl = px / sc;
    float inside = 1.0 - smoothstep(-pxl, pxl, sd);
    float rim = gauss1(sd, 0.004 + 0.004 * p_membrane) + 0.35 * glow2(sd, 0.012) * p_glow;
    float gr = 0.5 + 0.5 * ln2(l * 10.0, 2.0, 0.2);
    col += (fl ? memC * 0.05 : u_ink * 0.08) * inside * (0.6 + 0.4 * gr) * p_cytoplasm + memC * rim * 0.9;
    if (!fl) col += u_ink * 0.25 * gauss1(sd - 0.012, 0.01);
    cover = max(cover, max(inside * 0.85, sat(rim)));
  }
  // nuclei: parent (fades in prometaphase), daughters (reform in telophase), cousin (always)
  float nr = 0.55 * p_nucleus;
  float parentN = 1.0 - st(0.16, 0.3);
  float daughterN = st(0.64, 0.8);
  for (int i = 0; i < 4; i++) {
    vec2 c; float r; float a; float m = 1.0;
    if (i == 0) { c = vec2(0.0); r = R0 * nr; a = parentN; }
    else if (i == 1) { c = c1; r = rD * nr; a = daughterN; }
    else if (i == 2) { c = c2; r = rD * nr; a = daughterN; m = -1.0; }
    else { c = cc; r = R0 * nr; a = 1.0; m = -1.0; }
    if (a <= 0.001) continue;
    vec2 l = (w - c) / r;
    float dn = length(l) - 1.0;
    float inN = 1.0 - smoothstep(-px / r, px / r, dn);
    float ch = chromatin(l, m);
    float dots = pow(sat(ch * 1.6 + 0.5), 3.0);
    col += dnaC * inN * a * (0.25 + 1.1 * dots) + dnaC * gauss1(dn, 0.06) * a * 0.5;
    // nucleolus
    col += mix(dnaC, u_ink, 0.5) * (1.0 - smoothstep(0.18, 0.24, length(l - vec2(0.25 * m, 0.15)))) * a * 0.6;
    cover = max(cover, inN * a);
  }
  // spindle + chromosomes (condense, align, separate, decondense)
  float cond = st(0.1, 0.28) * (1.0 - st(0.66, 0.8));
  float align = st(0.22, 0.36);
  float ana = st(0.4, 0.58);
  float spindle = st(0.18, 0.3) * (1.0 - st(0.6, 0.72));
  vec2 pole1 = vec2(mix(R0 * 0.75, DD + rD * 0.55, sep), 0.0), pole2 = -pole1;
  if (spindle > 0.001) {
    for (int s = 0; s < 2; s++) {
      vec2 pl = s == 0 ? pole1 : pole2;
      float dpole = length(w - pl);
      col += tubC * (gauss1(dpole, 0.012) * 1.2 + glow2(dpole, 0.03) * 0.25 * p_glow) * spindle;
      // astral rays
      float ang = atan(w.y - pl.y, w.x - pl.x);
      float ray = pow(0.5 + 0.5 * cos(ang * float(p_fibres) * 1.5), 30.0) * exp(-dpole * 9.0);
      col += tubC * ray * spindle * 0.5;
    }
  }
  if (cond > 0.001) {
    for (int i = 0; i < 8; i++) {
      if (i >= p_chromosomes) break;
      vec2 h = h22(vec2(float(i), 42.0));
      float fi = float(i) / max(1.0, float(p_chromosomes) - 1.0);
      vec2 scatter = (h - 0.5) * R0 * 0.8;
      vec2 plate = vec2(0.0, (fi - 0.5) * R0 * 1.1);
      vec2 cen = mix(scatter, plate, align);
      float ang = mix(h.x * TAU, PI * 0.5, align) + 0.1 * lsin(3.0, h.y);
      mat2 rm = rot(ang);
      float arm = 0.028 * (0.8 + 0.5 * h.y);
      for (int s = 0; s < 2; s++) {
        float sg = s == 0 ? 1.0 : -1.0;
        vec2 pl = s == 0 ? pole1 : pole2;
        vec2 cs = mix(cen + vec2(sg * 0.006, 0.0), mix(pl * 0.82, pl + (plate - pl) * 0.2 * 0.0, 0.0) + vec2(0.0, plate.y * 0.35), ana);
        // chromatid arms trail back toward the plate during anaphase (V shape)
        vec2 dA = rm * vec2(0.0, arm);
        vec2 tail = vec2(-sg * 0.02 * ana, 0.0);
        float dc = min(sdSeg(w, cs, cs + dA + tail), sdSeg(w, cs, cs - dA + tail));
        float th = 0.0075;
        float chrom = 1.0 - smoothstep(th - px, th + px, dc);
        col += mix(dnaC, u_ink, 0.25) * chrom * cond * 1.4 + dnaC * glow2(dc, 0.01) * cond * 0.2 * p_glow;
        cover = max(cover, chrom * cond);
        // kinetochore fibre from the pole
        if (spindle > 0.01) {
          float df = sdSeg(w, pl, cs);
          col += tubC * line(df, 0.0018) * spindle * 0.55;
        }
      }
    }
  }
  // microscope field of view (hides the generation seam)
  float fov = 1.0 - smoothstep(p_field * 0.62, p_field * 0.95, length(uv));
  col = aces(col * 1.1) * fov;
  return vec4(col, max(cover * fov, max(col.r, max(col.g, col.b))));
}

files.styles/morphogen.glsl:
// Morphogen — Turing patterns: spots, stripes and labyrinths bloom and morph from a band-limited wave field.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 p = uv + p_warp * 0.06 * vec2(lfbm(uv * 2.0, 3, 1.0, 0.3), lfbm(uv * 2.0 + 5.0, 3, 1.0, 0.3));
  float k = 60.0 / p_wavelength;
  float f = 0.0, fx = 0.0, fy = 0.0;
  int N = p_waves;
  for (int i = 0; i < 24; i++) {
    if (i >= N) break;
    float fi = float(i);
    float a = p_hex ? TAU * (fi / 3.0) + (fi >= 3.0 ? h11(fi) * PI : 0.0) : h11(fi) * PI;
    vec2 d = vec2(cos(a), sin(a));
    float ph = h11(fi + 30.0) * TAU + TAU * float(p_drift) * u_p * (h11(fi + 60.0) < 0.5 ? 1.0 : -1.0);
    float s = dot(p, d) * k + ph;
    f += cos(s); fx += -sin(s) * d.x * k; fy += -sin(s) * d.y * k;
  }
  float nrm = 1.0 / sqrt(float(N));
  f *= nrm; fx *= nrm; fy *= nrm;
  // threshold sweeps across the frame (Pearson-map gradient) and breathes over the loop
  float thr = (p_feed - 0.5) * 1.6 + p_sweep * uv.x * 1.2 + 0.35 * p_breathe * lsin(1.0, 0.0);
  float sharp = mix(0.6, 0.04, p_sharp);
  float m = smoothstep(thr - sharp, thr + sharp, f);
  // relief shading from the field gradient
  vec3 N3 = normalize(vec3(-fx, -fy, k * 2.5 / (p_relief + 0.05)) );
  vec3 L = normalize(vec3(-0.5, 0.6, 0.7));
  float dif = sat(dot(N3, L)) * 0.7 + 0.3;
  float spec = pow(sat(dot(reflect(-L, N3), vec3(0.0, 0.0, 1.0))), 30.0) * p_specular * m;
  float hue = fract(f * 0.12 + float(p_cycle) * u_p * 0.0 + uv.y * 0.2);
  vec3 c = mix(u_a0, mix(u_a1, u_a2, sat(uv.y + 0.5)), sat(0.5 + 0.5 * sin(TAU * (hue + u_p * float(p_cycle)))));
  vec3 col = c * m * dif + u_ink * spec;
  col += c * 0.15 * smoothstep(thr - 0.8, thr, f) * (1.0 - m);
  return vec4(col, sat(m + 0.15 * smoothstep(thr - 0.8, thr, f)));
}

files.styles/neural-arbor.glsl:
// Neural Arbor — dendritic trees grow from somata, action potentials race out along every branch.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float g = mix(0.3, 1.0, growEnv(0.35)) * p_growth;
  vec3 col = vec3(0.0); float cover = 0.0;
  float px = aa();
  for (int n = 0; n < 6; n++) {
    if (n >= p_neurons) break;
    vec2 hn = h22(vec2(float(n), 3.7));
    vec2 c = p_neurons == 1 ? vec2(0.0) : (hn - 0.5) * A * 1.5;
    c += 0.03 * p_drift * lc(1.0, hn.x);
    vec2 q = uv - c;
    float reach = 0.9 * p_length;
    if (length(q) > reach * 1.25 + 0.05) continue;
    float sr = 0.026 * p_soma;
    float ds = length(q) - sr * (1.0 + 0.1 * lsin(2.0, hn.y) + 0.12 * ln2(q * 30.0, 1.0, 0.3));
    float soma = 1.0 - smoothstep(-px, px, ds);
    col += u_a2 * glow2(max(ds, 0.0), 0.012) * 0.7 * p_glow + mix(u_a2, u_ink, 0.6) * soma * (0.6 + 0.4 * sat(-ds / sr * 3.0));
    cover = max(cover, soma);
    for (int b = 0; b < 9; b++) {
      if (b >= p_branches) break;
      float fb = float(b);
      vec2 hb = h22(vec2(float(n) * 17.0 + fb, 9.1));
      float ang = TAU * (fb + 0.4 * (hb.x - 0.5)) / float(p_branches);
      vec2 pos = c + vec2(cos(ang), sin(ang)) * sr * 0.9;
      float along = 0.0;
      float seg = reach / float(p_segments) * (0.7 + 0.5 * hb.y);
      for (int s = 0; s < 14; s++) {
        if (s >= p_segments) break;
        float fs = float(s) / float(p_segments);
        if (fs > g) break;
        float grow = sat((g - fs) * float(p_segments));
        vec2 hs = h22(vec2(float(n) * 131.0 + fb * 13.0, float(s)));
        ang += (hs.x - 0.5) * 1.6 * p_curl + 0.12 * p_curl * lsin(1.0, hs.y + fs * 0.3);
        float L = seg * (1.0 - fs * 0.45);
        vec2 nxt = pos + vec2(cos(ang), sin(ang)) * L * grow;
        float dseg = sdSeg(uv, pos, nxt);
        float w = mix(0.009, 0.0022, fs) * p_thickness;
        if (dseg < w * 12.0 + 0.02) {
          float t = along + L * sat(dot(uv - pos, nxt - pos) / max(1e-6, dot(nxt - pos, nxt - pos)));
          float sp = pulse(t / reach * 1.3, float(p_spikes), hb.x, 0.035);
          vec2 f = fiber(dseg, w);
          col += mix(u_ink * 0.7, u_a0, 0.35 + 0.65 * fs) * f.x + u_a0 * f.y * 0.12 * p_glow + u_a1 * sp * (f.x * 1.8 + f.y * 0.5) * p_spikeGlow;
          cover = max(cover, f.x);
        }
        // sub-branch (culled by its maximum extent)
        if (hs.y < p_branching && dseg < L * 2.4 + 0.02) {
          float sa = ang + (hs.x < 0.5 ? -1.0 : 1.0) * (0.55 + 0.4 * hs.y);
          vec2 sq = mix(pos, nxt, 0.6); float salong = along + L * 0.6;
          for (int k = 0; k < 5; k++) {
            float fk = float(k) / 5.0;
            float sg = sat((g - fs) * float(p_segments) * 0.8 - fk);
            if (sg <= 0.0) break;
            vec2 hk = h22(vec2(float(n) * 71.0 + fb * 7.0 + float(s), float(k) + 40.0));
            sa += (hk.x - 0.5) * 1.2 * p_curl;
            float SL = L * 0.55 * (1.0 - fk * 0.4);
            vec2 sn = sq + vec2(cos(sa), sin(sa)) * SL * sg;
            float d2 = sdSeg(uv, sq, sn);
            float w2 = w * 0.6 * (1.0 - fk * 0.5);
            if (d2 < w2 * 12.0 + 0.012) {
              vec2 f2 = fiber(d2, w2);
              float sp2 = pulse((salong + SL * fk) / reach * 1.3, float(p_spikes), hb.x, 0.035);
              col += mix(u_ink * 0.5, u_a0, 0.6) * f2.x * 0.8 + u_a0 * f2.y * 0.08 * p_glow + u_a1 * sp2 * f2.x * 1.4 * p_spikeGlow;
              float spn = step(0.7, hk.y) * (1.0 - smoothstep(0.0, px * 1.5, length(uv - sn) - w2 * 1.3));
              col += u_a2 * spn;
              cover = max(cover, max(f2.x, spn));
            }
            salong += SL; sq = sn;
          }
        }
        pos = nxt; along += L;
      }
    }
  }
  col = aces(col);
  return vec4(col, max(cover, max(col.r, max(col.g, col.b))));
}

files.styles/neural-lace.glsl:
// Neural Lace — a holographic brain turns inside a glowing filament mesh; data pulses race across the lace.
float NL_brain(vec3 p) {
  vec3 q = p; q.x = abs(q.x) - 0.12 * p_gap - 0.02;
  float e = length(q / vec3(0.3, 0.3, 0.42)) - 1.0;
  e *= 0.28;
  float folds = sin(p.x * 38.0 + sin(p.z * 21.0)) * sin(p.y * 34.0 + sin(p.x * 17.0)) * sin(p.z * 29.0);
  float d = e + folds * 0.006 * p_folds;
  // flatten the base a little (brainstem side)
  d = smax(d, -p.y - 0.23, 0.05);
  return d;
}
vec4 motif(vec2 uv, vec2 fc) {
  float ang = TAU * u_p * float(p_spin) + 0.6;
  vec3 ro = vec3(sin(ang) * 1.45, 0.25, cos(ang) * 1.45);
  vec3 f = normalize(-ro), r = normalize(cross(vec3(0.0, 1.0, 0.0), f)), u = cross(f, r);
  vec3 rd = normalize(f * 1.7 + uv.x * r + uv.y * u);
  vec3 col = vec3(0.0); float a = 0.0;
  float t = 0.6, hit = 0.0; float glowAcc = 0.0;
  for (int i = 0; i < 70; i++) {
    vec3 p = ro + rd * t;
    float d = NL_brain(p);
    glowAcc += exp(-abs(d) * 60.0) * 0.02;
    if (d < 0.001) { hit = 1.0; break; }
    t += max(d * 0.8, 0.004);
    if (t > 3.0) break;
  }
  if (hit > 0.0) {
    vec3 p = ro + rd * t;
    vec2 e = vec2(0.0015, -0.0015);
    vec3 n = normalize(e.xyy * NL_brain(p + e.xyy) + e.yyx * NL_brain(p + e.yyx) + e.yxy * NL_brain(p + e.yxy) + e.xxx * NL_brain(p + e.xxx));
    float fres = pow(1.0 - sat(dot(n, -rd)), 2.0);
    // lace: triangular grid lines in object space (three families of planes)
    float dens = 18.0 * p_density;
    float l1 = abs(fract(dot(p, vec3(1.0, 0.0, 0.0)) * dens) - 0.5);
    float l2 = abs(fract(dot(p, vec3(0.5, 0.866, 0.0)) * dens) - 0.5);
    float l3 = abs(fract(dot(p, vec3(0.5, -0.433, 0.75)) * dens) - 0.5);
    float lm = min(l1, min(l2, l3));
    float lw = 0.04 * p_width;
    float lace = 1.0 - smoothstep(lw, lw + 0.05, lm);
    // pulses travel radially outward over the lace
    float pr = length(p) * 3.0;
    float pul = 0.0;
    for (int k = 0; k < 4; k++) { if (k >= p_pulses) break; pul += pulse(pr + dot(p, vec3(float(k) - 1.5, 1.0, 0.3)) * 0.5, float(p_pulseSpeed), float(k) * 0.23, 0.05); }
    vec3 holo = u_a0 * (0.15 + 0.85 * fres) * p_opacity;
    col = holo + u_a1 * lace * (0.5 + 1.8 * pul) * (0.35 + 0.65 * fres) + u_ink * lace * pul * 0.8;
    col *= 0.85 + 0.15 * sin(fc.y * 2.2 + u_p * TAU * 0.0) * p_scan;
    a = sat(0.25 * p_opacity + fres * 0.6 + lace * 0.8);
  }
  col += u_a0 * glowAcc * p_glow;
  col = aces(col * 1.2);
  return vec4(col, max(a, max(max(col.r, col.g), col.b)));
}

files.styles/organoid-post.glsl:
// Organoid (pass 2) — upsample with a soft bloom and tone map.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 t = fc / u_res;
  vec4 c = texture(u_buf0, t);
  vec2 px = 1.0 / u_res;
  vec3 bl = vec3(0.0);
  for (int i = 0; i < 8; i++) { float a = float(i) * 0.785398; bl += texture(u_buf0, t + vec2(cos(a), sin(a)) * px * 6.0).rgb; }
  bl /= 8.0;
  vec3 col = c.rgb + max(bl - 0.35, 0.0) * 0.6 * p_innerGlow;
  col = aces(col * 1.2);
  return vec4(col, max(c.a, max(col.r, max(col.g, col.b))));
}

files.styles/organoid-scene.glsl:
// Organoid (pass 1, half resolution) — raymarched cell cluster.
float ORG_cellR(int i) { return 0.11 * p_cellSize * (0.8 + 0.4 * h11(float(i) + 7.0)); }
vec3 ORG_center(int i, int N) {
  float fi = float(i) + 0.5;
  float y = 1.0 - 2.0 * fi / float(N);
  float r = sqrt(1.0 - y * y);
  float th = fi * 2.39996323;
  vec3 d = vec3(cos(th) * r, y, sin(th) * r);
  float h = h11(float(i));
  float rad = p_radius * (1.0 + p_bloom * 0.35 * (0.5 + 0.5 * lsin(float(p_budding), h)));
  return d * rad + 0.03 * p_bloom * vec3(lc(1.0, h), lsin(2.0, h * 3.0));
}
float ORG_map(vec3 p, int N) {
  float d = 1e9;
  for (int i = 0; i < 48; i++) {
    if (i >= N) break;
    float r = ORG_cellR(i) * (1.0 + 0.25 * p_bloom * lsin(float(p_budding), h11(float(i) + 2.0)));
    d = smin(d, length(p - ORG_center(i, N)) - r, 0.06 * p_smooth + 0.005);
  }
  return d + p_displace * 0.01 * snoise(p * 18.0 + vec3(lc(1.0, 0.0), 0.0));
}
vec4 motif(vec2 uv, vec2 fc) {
  int N = p_cells;
  float ang = TAU * u_p * float(p_spin);
  vec3 ro = vec3(sin(ang) * 1.6, 0.35, cos(ang) * 1.6);
  vec3 ta = vec3(0.0);
  vec3 f = normalize(ta - ro), r = normalize(cross(vec3(0.0, 1.0, 0.0), f)), u = cross(f, r);
  vec3 rd = normalize(f * 1.6 + uv.x * r + uv.y * u);
  float bound = p_radius * 1.6 + 0.25;
  // bounding sphere
  float b = dot(ro, rd), c = dot(ro, ro) - bound * bound, disc = b * b - c;
  vec3 col = vec3(0.0); float a = 0.0;
  // nuclei seen through the translucent membrane (ray-to-centre distance)
  float nuc = 0.0;
  for (int i = 0; i < 48; i++) {
    if (i >= N) break;
    vec3 cc = ORG_center(i, N);
    float t = dot(cc - ro, rd);
    float d = length(ro + rd * t - cc);
    nuc += exp(-pow(d / (ORG_cellR(i) * 0.38), 2.0)) * (0.6 + 0.4 * h11(float(i) + 9.0));
  }
  if (disc > 0.0) {
    float t = -b - sqrt(disc); t = max(t, 0.0);
    float hit = 0.0; int steps = 24 + int(40.0 * p_quality);
    for (int i = 0; i < 64; i++) {
      if (i >= steps) break;
      float d = ORG_map(ro + rd * t, N);
      if (d < 0.0015) { hit = 1.0; break; }
      t += d * 0.9;
      if (t > 4.0) break;
    }
    if (hit > 0.0) {
      vec3 p = ro + rd * t;
      vec2 e = vec2(0.002, -0.002);
      vec3 n = normalize(e.xyy * ORG_map(p + e.xyy, N) + e.yyx * ORG_map(p + e.yyx, N) + e.yxy * ORG_map(p + e.yxy, N) + e.xxx * ORG_map(p + e.xxx, N));
      vec3 L = normalize(vec3(cos(p_light * TAU), 0.8, sin(p_light * TAU)));
      float dif = sat(dot(n, L));
      float fres = pow(1.0 - sat(dot(n, -rd)), 3.0);
      float thick = sat(ORG_map(p - n * 0.06, N) / -0.06);
      float sss = (1.0 - thick) * p_translucency;
      vec3 skin = mix(u_a2 * 0.6, u_ink * 0.9, 0.35 * dif);
      col = skin * (0.12 + 0.6 * dif) + u_a2 * sss * 0.5 + u_a0 * fres * p_rim * 1.4;
      col += mix(u_a1, u_ink, 0.2) * nuc * p_innerGlow * (0.4 + sss) * 0.7;
      col += u_ink * pow(sat(dot(reflect(-L, n), -rd)), 40.0) * 0.5;
      a = 1.0;
    }
  }
  col += u_a1 * nuc * p_innerGlow * 0.05 * (1.0 - a);
  return vec4(col, a);
}

files.styles/physarum.glsl:
// Physarum — a slime-mould transport network: veins pulse with shuttle streaming as the organism forages.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 p = uv * p_scale * 3.0;
  vec2 wp = p + p_warp * 0.8 * vec2(lfbm(p * 0.5, 3, 1.0, 0.25), lfbm(p * 0.5 + 9.0, 3, 1.0, 0.25));
  // major veins: Voronoi edges on the warped domain
  vec3 v = lvoro(wp, 0.9, float(p_flow), 0.35);
  float edge = v.y - v.x;
  float vw = 0.06 * p_veins;
  float vein = 1.0 - smoothstep(vw * 0.5, vw * 0.5 + 0.03, edge);
  // capillary mesh: ridged noise
  float cap = pow(lridge(wp * 1.7, 4, float(p_flow), 0.3), 3.0);
  cap = smoothstep(0.55 - 0.25 * p_capillary, 0.95, cap) * p_capillary;
  // sparsity mask: the organism covers only part of the plate, fronts advance and retreat
  float cover = smoothstep(-0.2, 0.3, lfbm(p * 0.25 + 3.0, 3, 1.0, 0.35) + 0.6 - p_sparsity * 0.72);
  // shuttle streaming: peristaltic waves along the network
  float wave = 0.5 + 0.5 * sin(v.x * 12.0 * p_wavelength - TAU * float(p_flow) * u_p * 2.0 + v.z * TAU);
  float thick = vein * (0.55 + 0.45 * wave * p_pulse);
  float tube = max(thick, cap * 0.7) * cover;
  // food sources: bright nodes that the veins converge on
  float food = 0.0;
  for (int i = 0; i < 6; i++) {
    if (i >= p_food) break;
    vec2 h = h22(vec2(float(i), 5.0));
    vec2 c = (h - 0.5) * M_asp() * 0.85;
    float d = length(uv - c);
    food += gauss1(d, 0.02) * (0.8 + 0.2 * lsin(2.0, h.x)) + glow2(d, 0.04) * 0.2;
    tube = max(tube, (1.0 - smoothstep(0.0, 0.15, d)) * vein);
  }
  float core = pow(tube, 1.5);
  vec3 col = mix(u_a2, u_a1, core) * tube * 1.2 + u_ink * pow(core, 4.0) * 0.8 * wave;
  col += u_a1 * glow2(1.0 - tube, 0.3) * 0.08 * p_glow * cover;
  col += u_a0 * food * p_glow;
  col = aces(col);
  return vec4(col, max(tube * 0.9, max(col.r, max(col.g, col.b))));
}

files.styles/protein-fold.glsl:
// Protein Fold — a random coil collapses into helices and sheets, holds its fold, then melts back to chaos.
vec3 foldedPos(int i, int N) {
  // helix bundle / sheet: segments of ~11 residues laid antiparallel around a ring
  int K = max(2, N / 11);
  float segLen = float(N) / float(K);
  float fs = float(i) / segLen;
  int s = int(floor(fs)); float j = fract(fs);
  float dir = (s % 2 == 0) ? 1.0 : -1.0;
  float a0 = TAU * float(s) / float(K);
  vec3 axis = vec3(cos(a0), 0.0, sin(a0)) * 0.11 * sqrt(float(K) / 4.0);
  float y = (j - 0.5) * 0.36 * dir;
  bool helix = h11(float(s) + 17.0) < p_helix;
  vec3 pos = axis + vec3(0.0, y, 0.0);
  if (helix) { float a = float(i) * 1.0; pos += vec3(cos(a), 0.0, sin(a)) * 0.05; pos.y *= 0.8; }
  else { vec3 side = normalize(vec3(-axis.z, 0.0, axis.x) + 1e-4); pos += side * (i % 2 == 0 ? 0.018 : -0.018); }
  return pos;
}
vec4 motif(vec2 uv, vec2 fc) {
  int N = p_residues;
  float fold = smoothstep(0.08, 0.4, u_p) * (1.0 - smoothstep(0.4 + 0.5 * p_hold, 0.95, u_p));
  float ang = TAU * u_p * float(p_spin);
  mat2 R = rot(ang);
  float persp = p_perspective;
  // pass 1: random-walk centroid
  vec3 w = vec3(0.0), cen = vec3(0.0);
  for (int i = 0; i < 72; i++) {
    if (i >= N) break;
    vec3 h = h33(vec3(float(i), 5.0, 2.0)) - 0.5;
    w += normalize(h + 1e-3) * 0.045;
    cen += w;
  }
  cen /= float(N);
  vec3 prev = vec3(0.0); vec2 prevS = vec2(0.0); float prevZ = 0.0;
  float bestZ = -1e9; vec3 bestC = vec3(0.0); float bestShade = 0.0; float hit = 0.0; float glowAcc = 0.0;
  w = vec3(0.0);
  for (int i = 0; i < 72; i++) {
    if (i >= N) break;
    vec3 h = h33(vec3(float(i), 5.0, 2.0)) - 0.5;
    w += normalize(h + 1e-3) * 0.045;
    vec3 coil = (w - cen) * 1.4 * p_coil + 0.02 * vec3(lc(2.0, h.x), lsin(1.0, h.y + h.z));
    vec3 pos = mix(coil, foldedPos(i, N), fold);
    pos.xz = R * pos.xz;
    float sc = 1.0 / (1.0 + pos.z * persp * -1.2);
    vec2 S = pos.xy * sc * 2.5;
    float Z = pos.z;
    if (i > 0) {
      vec2 pa = uv - prevS, ba = S - prevS;
      float t = sat(dot(pa, ba) / max(dot(ba, ba), 1e-8));
      float d = length(pa - ba * t);
      float z = mix(prevZ, Z, t);
      float r = max(0.026 * p_radius * mix(1.0, sc, 0.5), 2.5 * aa());
      if (d < r) {
        float nz = sqrt(1.0 - (d / r) * (d / r));
        float zz = z + nz * r;
        if (zz > bestZ) {
          bestZ = zz; hit = 1.0;
          float fi = (float(i) - 1.0 + t) / float(N);
          int seg = int(floor((float(i) + t) / (float(N) / float(max(2, N / 11)))));
          bool hel = h11(float(seg) + 17.0) < p_helix;
          vec3 c = p_colour == COLOUR_INDEX ? mix(mix(u_a0, u_a1, sat(fi * 2.0)), u_a2, sat(fi * 2.0 - 1.0))
                 : p_colour == COLOUR_STRUCTURE ? (fold > 0.5 ? (hel ? u_a0 : u_a1) : mix(u_ink * 0.6, hel ? u_a0 : u_a1, fold * 2.0))
                 : (h11(float(i) + 3.0) < 0.45 ? u_a2 : u_ink * 0.75);
          bestC = c; bestShade = nz;
        }
      }
      glowAcc += glow2(d, 0.025) * 0.03;
    }
    prevS = S; prevZ = Z;
  }
  vec3 col = vec3(0.0); float a = 0.0;
  if (hit > 0.0) {
    float depthShade = mix(1.0, 0.55 + 0.45 * sat(bestZ * 3.0 + 0.5), p_depthShade);
    float rim = smoothstep(0.35, 0.0, bestShade) * p_outline;
    col = bestC * (0.25 + 0.75 * bestShade) * depthShade + u_ink * pow(bestShade, 18.0) * 0.6;
    col = mix(col, u_bg * 0.3, rim);
    a = 1.0;
  }
  col += mix(u_a0, u_a1, 0.5) * glowAcc * p_glow * (1.0 - a);
  col = aces(col * 1.1);
  return vec4(col, max(a, max(col.r, max(col.g, col.b))));
}

files.styles/synaptic-cleft.glsl:
// Synaptic Cleft — vesicles dock and fuse, neurotransmitter diffuses across the cleft and lights the receptors.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float px = aa();
  vec2 q = uv / p_scale;
  float cw = 0.05 * p_cleft;              // half-width of the cleft
  float curv = p_curvature * 0.35;
  // pre-synaptic bouton: dome above, post-synaptic membrane below
  float preY = cw + curv * q.x * q.x;
  float postY = -cw - curv * 0.6 * q.x * q.x;
  float cyc = float(p_rate);
  float ph = fract(u_p * cyc);            // release cycle
  vec3 col = vec3(0.0); float cover = 0.0;
  // membranes: lipid bilayer (two lines) with texture
  float dPre = uv.y / p_scale - preY, dPost = uv.y / p_scale - postY;
  float bil = 0.006;
  float mPre = line(abs(dPre - bil), 0.0035 / p_scale) + line(abs(dPre - bil * 2.4), 0.0035 / p_scale);
  float mPost = line(abs(dPost + bil), 0.0035 / p_scale) + line(abs(dPost + bil * 2.4), 0.0035 / p_scale);
  float grain = 0.6 + 0.4 * ln2(q * 60.0, 1.0, 0.2);
  // cytoplasm tint
  vec3 preFill = u_a2 * 0.10 * smoothstep(0.0, 0.03, dPre) * (0.6 + 0.4 * grain) + u_a0 * 0.08 * gauss1(dPre, 0.03);
  vec3 postFill = u_a0 * 0.09 * smoothstep(0.0, 0.03, -dPost) * (0.6 + 0.4 * grain) + u_a0 * 0.1 * gauss1(dPost, 0.03);
  col += preFill + postFill + u_ink * 0.55 * (mPre + mPost) * grain;
  cover = max(cover, max(sat(mPre + mPost), 0.35 * (smoothstep(0.0, 0.02, dPre) + smoothstep(0.0, 0.02, -dPost))));
  // receptors on the post membrane
  float rs = 0.028 / p_receptors;
  float rx = q.x / rs; float rcell = floor(rx), rf = fract(rx) - 0.5;
  // activation: sum of transmitter arrival near this receptor
  float arrive = 0.0;
  // vesicles
  for (int i = 0; i < 40; i++) {
    if (i >= p_vesicles) break;
    vec2 h = h22(vec2(float(i), 7.0));
    float vx = (h.x - 0.5) * 1.6 * A.x / p_scale;
    float r = 0.024 * p_vesSize * (0.8 + 0.4 * h.y);
    float docked = step(h.y, 0.55);
    float t = fract(ph + h.y * 0.35);  // vesicle local cycle
    float depth = mix(0.06 + h.y * 0.25, 0.0, docked * smoothstep(0.0, 0.4, t));
    vec2 home = vec2(vx + 0.01 * lsin(2.0, h.x), preY + r + 0.012 + depth);
    home.y = preY + r + 0.004 + depth + 0.2 * h.y * (1.0 - docked);
    home += 0.006 * lc(3.0, h.x) * (1.0 - docked);
    float fuse = docked * smoothstep(0.4, 0.55, t) * (1.0 - smoothstep(0.85, 1.0, t));
    float dv = length(q - home) - r * (1.0 - 0.6 * fuse);
    float ring = line(abs(dv), 0.003 / p_scale) * (1.0 - fuse * 0.7);
    float fill = (1.0 - smoothstep(-px, px, dv)) * (1.0 - fuse);
    col += u_a2 * (ring * 1.4 + fill * 0.45) + u_a2 * glow2(abs(dv), 0.01) * 0.25 * p_glow;
    cover = max(cover, max(ring, fill * 0.8));
    // transmitter cloud released on fusion
    if (docked > 0.5) {
      float rel = smoothstep(0.5, 0.55, t);
      float age = sat((t - 0.5) / 0.45);
      for (int j = 0; j < 14; j++) {
        if (float(j) >= float(p_particles)) break;
        vec2 hj = h22(vec2(float(i) * 31.0 + float(j), 3.0));
        vec2 dir = normalize(vec2(hj.x - 0.5, -0.6 - hj.y));
        float spread = sqrt(age) * (0.03 + 0.09 * p_diffusion * hj.y);
        vec2 pp = vec2(home.x, preY) + dir * spread * (1.0 + 2.0 * p_diffusion) + 0.01 * p_diffusion * lc(1.0, hj.x) * age;
        pp.y = max(pp.y, postY + 0.004);
        float dp = length(q - pp);
        float life = rel * (1.0 - smoothstep(0.8, 1.0, age));
        col += u_a1 * (1.0 - smoothstep(0.003 * p_partSize, 0.003 * p_partSize + px, dp)) * life * 2.0 + u_a1 * glow2(dp, 0.006) * life * 0.35 * p_glow;
        arrive += life * gauss1(pp.x - (rcell + 0.5) * rs, rs * 0.6) * step(pp.y, postY + 0.012);
      }
    }
  }
  // receptor glyphs: little channel proteins that open when transmitter lands
  float open = sat(arrive * 0.8);
  vec2 rp = vec2(rf * rs, q.y - postY + 0.008);
  float rb = sdBox(rp, vec2(rs * 0.18, 0.009));
  float rgap = sdBox(rp, vec2(rs * 0.05 * (0.4 + open), 0.012));
  float rec = (1.0 - smoothstep(0.0, px, max(rb, -rgap))) * step(0.25, h11(rcell + 3.0));
  col += mix(u_ink * 0.4, u_a1 * 2.0, open) * rec + u_a1 * open * glow2(length(rp), 0.015) * 0.5 * p_glow * step(0.25, h11(rcell + 3.0));
  cover = max(cover, rec);
  // post-synaptic potential glow spreading below
  col += u_a0 * 0.25 * p_glow * smoothstep(0.0, -0.3, dPost) * pow(sat(arrive * 0.15), 0.5) * gauss1(dPost, 0.06);
  col = aces(col * 1.15);
  return vec4(col, max(cover, max(col.r, max(col.g, col.b))));
}
